head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf00003";
scwin.emb1 = null;
scwin.emb2 = null;
scwin.emb3 = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.emb1 = $c.util.getComponent('emb1');
        scwin.emb2 = $c.util.getComponent('emb2');
        scwin.emb3 = $c.util.getComponent('emb3');
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf00003.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_viewMv_onclick
 * @description btn_viewMv 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_viewMv_onclick = function(e){
    try {
        scwin.viewMv(1)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00003.btn_viewMv_onclick' }); }
};

/**
 * @method
 * @name btn_viewMv_2_onclick
 * @description btn_viewMv_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_viewMv_2_onclick = function(e){
    try {
        scwin.viewMv(2)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00003.btn_viewMv_2_onclick' }); }
};

/**
 * @method
 * @name btn_viewMv_3_onclick
 * @description btn_viewMv_3 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_viewMv_3_onclick = function(e){
    try {
        scwin.viewMv(3)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00003.btn_viewMv_3_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name viewMv
 * @description view Mv 처리
 * @param {*} gubun gubun
 * @returns {void}
 * @hidden N
 */
scwin.viewMv = function (gubun) {
    $("#movie" + gubun).attr("style", "display:;");
    scwin.emb1.setStyle("display", "none");
    scwin.emb2.setStyle("display", "none");
    scwin.emb3.setStyle("display", "none");
    if (gubun === "1") {
        $c.util.getComponent("movie2").setStyle("display", "none");
        $c.util.getComponent("movie3").setStyle("display", "none");
        self.setTimeout(function(){ scwin.playMovie('emb1') }, 1000);
    } else {
        if (gubun === "2") {
            $c.util.getComponent("movie1").setStyle("display", "none");
            $c.util.getComponent("movie3").setStyle("display", "none");
            self.setTimeout(function(){ scwin.playMovie('emb2') }, 1000);
        } else {
            if (gubun === "3") {
                $c.util.getComponent("movie1").setStyle("display", "none");
                $c.util.getComponent("movie2").setStyle("display", "none");
                self.setTimeout(function(){ scwin.playMovie('emb3') }, 1000);
            }
        }
    }
    /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
};

/**
 * @method
 * @name playMovie
 * @description play Movie 처리
 * @param {*} oMyObj oMyObj
 * @returns {void}
 * @hidden N
 */
scwin.playMovie = function (oMyObj) {
    const div_explan = $c.util.getComponent('movies');
    if (div_explan) {
        const explan_a = div_explan.getElementsByTagName('embed');
        for (let i = 0; i < explan_a.length; i++) {
            const ep_e = explan_a[i];
            if (ep_e.id === oMyObj) {
                ep_e.play();
            } else {
                ep_e.stop();
            }
        }
    }
};
